import re, json

d = os.environ['RLM_SESSION_DIR']
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
lines = t.strip().split('\n')

line_11 = lines[11]
content_match = re.search(r'"text":"([^"]+)"', line_11)
text = content_match.group(1).replace('\\n', '\n').replace('\\\\', '\\')

demo_input_start = text.find('Demo pair 1 input (24x24):\n')
demo_grid_str = text[demo_input_start + len('Demo pair 1 input (24x24):\n'):text.find('Demo pair 1 output')]
rows = [line.split() for line in demo_grid_str.split('\n') if line.strip() and line.strip()[0].isdigit()]
demo_input = [[int(x) for x in row] for row in rows]

output = [[2,7,9,7,5], [6,9,2,9,5], [3,2,9,7,8], [8,3,6,2,5], 
          [8,6,6,5,5], [7,2,6,2,6], [9,8,8,3,2], [5,8,2,8,6]]

# Look for matching subgrids
def find_subgrid(grid, target_rows):
    h, w = len(target_rows), len(target_rows[0])
    H, W = len(grid), len(grid[0])

    for r in range(H - h + 1):
        for c in range(W - w + 1):
            match = True
            for dr in range(h):
                for dc in range(w):
                    if grid[r+dr][c+dc] != target_rows[dr][dc]:
                        match = False
                        break
                if not match:
                    break
            if match:
                return (r, c)
    return None

# Try to find each output row in the input
for i, target_row in enumerate(output):
    loc = find_subgrid(demo_input, [target_row])
    if loc:
        print(f"Output row {i} found at input ({loc[0]}, {loc[1]})")
    else:
        print(f"Output row {i} NOT FOUND")

