        def find_grids(obj, indent=""):
            results = []
            if isinstance(obj, dict):
                for k, v in obj.items():
                    results.append((k, v))
                    results.extend(find_grids(v, indent + "  "))
            elif isinstance(obj, list):
                for idx, item in enumerate(obj):
                    results.append((f"[{idx}]", item))
